/* Screen-level interactions: tabs, sample selection, draft preview, connection checks. */
window.renderPrototype=function(p){
  const model=window.ULIKE_PROTOTYPES[p.id];
  if(!model){shell('<h1>原型配置缺失</h1>','未找到','projects');return;}
  const safe=esc;
  const connected=window.ULIKE_API.available(p.id);
  const sample=model.rows[0];
  let feedback='';
  shell('<a class="back" href="#/projects">← 返回项目目录</a><div class="proto-title"><div><p class="eyebrow">PROJECT '+p.num+' / 22 · '+safe(p.category)+'</p><h1>'+safe(p.title)+'</h1><p>'+safe(p.desc)+'</p></div><span class="proto-mode">前端原型 · 合成样例</span></div><div class="proto-connection"><span class="proto-connection-icon">'+(connected?'◉':'○')+'</span><div><strong>'+ (connected?'已配置后端网关，尚未验证服务':'未接入数据库与 API')+'</strong><p>'+ (connected?'点击“检查连接”读取服务健康状态；数据写入仍由后端控制。':'以下是可操作的界面样例。列表和数字不是实时业务数据；真实查询、生成、上传、同步与外部执行不可用。')+'</p></div><button class="btn" id="checkConnection">检查连接</button></div><div class="proto-metrics">'+[0,2,4].map(i=>'<div class="proto-metric"><small>'+safe(model.kpis[i])+'</small><strong>'+safe(model.kpis[i+1])+'</strong></div>').join('')+'</div><div class="proto-workspace"><section class="proto-main"><div class="proto-tabs" role="tablist">'+model.tabs.map((t,i)=>'<button type="button" class="proto-tab '+(i===0?'active':'')+'" role="tab" aria-selected="'+(i===0)+'" data-tab="'+i+'">'+safe(t)+'</button>').join('')+'</div><div id="protoPanel"></div></section><aside class="proto-aside"><div class="proto-aside-icon">✿</div><h3>这一页怎么体验？</h3><ol>'+p.flow.map(x=>'<li>'+safe(x)+'</li>').join('')+'</ol><div class="proto-side-note"><strong>接入边界</strong><p>'+safe(model.note)+'</p></div><div class="proto-side-note"><strong>预留接口</strong><p>健康检查 · 列表读取 · 受控提交。服务地址由站点配置文件指定，密钥只留在后端。</p></div></aside></div>',p.title+' / 原型','projects');
  function renderTab(index){
    document.querySelectorAll('.proto-tab').forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-selected',String(i===index))});
    const title=model.tabs[index];
    $('#protoPanel').innerHTML='<div class="proto-panel-head"><div><span class="eyebrow">'+safe(title)+' / PROTOTYPE VIEW</span><h2>'+safe(title)+'</h2><p>合成样例可查看；你的操作草稿保存在当前浏览器。</p></div><span class="proto-sample-tag">原型模式</span></div><div class="proto-screen">'+(index===0?primaryView():secondaryView(index))+'</div>';
    document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=()=>selectSample(Number(b.dataset.sample)));
    $('#protoForm')?.addEventListener('submit',e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));let err=validate(p,d);if(err){notify(err);return}let s=state(p),output=rule(p,d),title=d.name||d.title||d.supplier||d.file||d.item||d.project||d.kol||d.role||d.asin||d.model||d.question||d.prompt||d.feedback||d.filename||d.path||p.title;s.items.unshift({id:Date.now().toString(36)+Math.random().toString(36).slice(2,5),title,data:d,stage:0,result:output,created:stamp()});event(s,'创建原型任务「'+title+'」');persist(p,s);feedback=output;renderTab(0);notify('原型任务已保存到本机浏览器')});
    document.querySelectorAll('[data-proto-next]').forEach(b=>b.onclick=()=>moveRecord(b.dataset.protoNext));
    document.querySelectorAll('[data-proto-return]').forEach(b=>b.onclick=()=>moveRecord(b.dataset.protoReturn,true));
    document.querySelectorAll('[data-proto-delete]').forEach(b=>b.onclick=()=>deleteRecord(b.dataset.protoDelete));
    $('#protoChatForm')?.addEventListener('submit',e=>{e.preventDefault();let t=e.target.message.value.trim();if(!t)return;let s=state(p);s.messages.push({role:'user',text:t});s.messages.push({role:'assistant',text:p.id==='ask'?'已记录问题。请在接入只读数据库后确认统计口径与证据；当前不生成业务数值。':(/抱歉|理解/.test(t)?'安抚表达已覆盖。':'请先表达理解和歉意。')+' '+(/订单|核实|确认/.test(t)?'信息核验已覆盖。':'请补充核验步骤。')});event(s,'新增原型会话消息');persist(p,s);renderTab(index)});
    $('#protoAction')?.addEventListener('click',()=>{document.querySelector('[data-tab="0"]').click();$('#protoForm input, #protoForm textarea, #protoForm select')?.focus()});
  }
  function table(){return '<div class="proto-table-wrap"><table><thead><tr>'+model.cols.map(x=>'<th>'+safe(x)+'</th>').join('')+'</tr></thead><tbody>'+model.rows.map((row,i)=>'<tr><td><button class="proto-row-link" data-sample="'+i+'">'+safe(row[0])+'</button></td>'+row.slice(1).map(v=>'<td>'+safe(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
  function primaryView(){return '<div class="proto-primary"><div class="proto-data"><div class="proto-list-title"><h3>合成记录</h3><span>点击行查看详情</span></div>'+table()+'<div class="proto-detail" id="protoDetail"><span>01 / 合成记录</span><h3>'+safe(sample[0])+'</h3><p>'+model.cols.map((c,i)=>safe(c)+'：'+safe(sample[i])).join('　·　')+'</p></div><div class="proto-local-records"><div class="proto-list-title"><h3>我的原型任务</h3><span>本机保存 · 非生产数据</span></div>'+localRecords()+'</div></div><div class="proto-form-card"><div class="proto-list-title"><h3>新建操作草稿</h3><span>仅在当前浏览器计算</span></div><form id="protoForm"><div class="proto-fields">'+fields(p)+'</div><button class="btn primary" type="submit">'+safe(model.action)+' →</button></form><div id="protoOutput" class="proto-output" '+(feedback?'':'hidden')+'><strong>本地规则反馈</strong><p>'+safe(feedback)+'</p><small>浏览器计算，不会写入生产系统。</small></div></div></div>'}
  function secondaryView(index){
    const labels=model.tabs[index];
    if((p.id==='ask'||p.id==='reception')&&index===1){let s=state(p),messages=s.messages.length?s.messages:[{role:'assistant',text:p.id==='ask'?'请先输入业务问题；数据源未接入时，我会明确指出无法计算的指标。':'买家：订单迟迟没有送达，能帮我查一下吗？'}];return '<div class="proto-chat"><div class="proto-chat-history">'+messages.map(m=>'<div class="proto-chat-bubble '+safe(m.role)+'"><small>'+(m.role==='user'?'你':'原型助手')+'</small>'+safe(m.text)+'</div>').join('')+'</div><form id="protoChatForm"><input name="message" placeholder="输入一条消息，体验会话界面…" required><button class="btn primary">发送</button></form><p class="inline-note">本地规则回应。模型和业务数据库尚未接入。</p></div>'}
    return '<div class="proto-secondary"><div class="proto-secondary-art" aria-hidden="true">'+(['✧','✿','◇','▦'][index%4])+'</div><div><span class="eyebrow">'+safe(p.title)+'</span><h3>'+safe(labels)+'工作区</h3><p>'+safe(model.note)+'</p><button class="btn primary" id="protoAction">创建操作草稿 →</button></div></div><div class="proto-list-title"><h3>'+safe(labels)+' · 合成资料</h3><span>非实时数据</span></div>'+table()+'<div class="proto-local-records"><div class="proto-list-title"><h3>我的原型任务</h3><span>可推进本地状态</span></div>'+localRecords()+'</div>'}
  function titleFor(index){return model.tabs[index]+'的前端结构已预留'}
  function selectSample(i){const row=model.rows[i];$('#protoDetail').innerHTML='<span>'+String(i+1).padStart(2,'0')+' / 合成记录</span><h3>'+safe(row[0])+'</h3><p>'+model.cols.map((c,j)=>safe(c)+'：'+safe(row[j])).join('　·　')+'</p>'}
  function localRecords(){const s=state(p),arr=stages(p);if(!s.items.length)return '<p class="proto-empty">还没有操作草稿。填写表单即可创建一条，并体验项目状态变化。</p>';return '<div class="proto-record-list">'+s.items.slice(0,8).map(x=>'<div class="proto-record"><div><strong>'+safe(x.title)+'</strong><small>'+safe(x.created)+' · '+safe(arr[x.stage]||'待核对')+'</small></div><div><button class="btn" data-proto-next="'+x.id+'" '+(x.stage>=arr.length-1?'disabled':'')+'>'+(p.id==='qms'&&x.stage===2?'重新提交':'下一步')+'</button>'+(p.id==='qms'&&x.stage===1?'<button class="btn" data-proto-return="'+x.id+'">退回</button>':'')+'<button class="btn ghost" data-proto-delete="'+x.id+'" aria-label="删除 '+safe(x.title)+'">×</button></div></div>').join('')+'</div>'}
  const external=['nas','legal','autorecruit','meeting','deploy','aigc','translation'];
  function moveRecord(id,isReturn=false){let s=state(p),x=s.items.find(r=>r.id===id),arr=stages(p);if(!x)return;if(external.includes(p.id)&&x.stage>=arr.length-2){feedback='此步骤需要真实后端、身份和外部系统。当前未接入数据库和 API，无法把任务标记为真实完成。';renderTab(0);notify('未接入数据库和 API，外部动作不可执行');return}if(p.id==='qms'&&isReturn&&x.stage===1)x.stage=2;else if(p.id==='qms'&&x.stage===1)x.stage=3;else if(p.id==='qms'&&x.stage===2)x.stage=1;else if(x.stage<arr.length-1)x.stage++;else return;event(s,'「'+x.title+'」→ '+arr[x.stage]+'（本地原型）');persist(p,s);renderTab(0);notify('本地原型状态已更新；未写入数据库')}
  function deleteRecord(id){let s=state(p);s.items=s.items.filter(x=>x.id!==id);event(s,'删除一条本地原型任务');persist(p,s);renderTab(0)}
  document.querySelectorAll('.proto-tab').forEach(b=>b.onclick=()=>renderTab(Number(b.dataset.tab)));
  $('#checkConnection').onclick=async()=>{try{const data=await window.ULIKE_API.request(p.id,'health');notify('接口已响应；请核对该服务的业务数据范围');$('#checkConnection').textContent='连接已响应';console.info('service health',p.id,data)}catch(e){notify(e.message)}};
  renderTab(0);
};
